import{_ as a,o as s,c as t,a0 as i}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Running the current tests and feedback loop","description":"","frontmatter":{"docLocale":"en","counterpart":"/testing/feedback-loop"},"headers":[],"relativePath":"en/testing/feedback-loop.md","filePath":"en/testing/feedback-loop.md"}'),n={name:"en/testing/feedback-loop.md"};function r(o,e,l,h,d,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="running-the-current-tests-and-feedback-loop" tabindex="-1">Running the current tests and feedback loop <a class="header-anchor" href="#running-the-current-tests-and-feedback-loop" aria-label="Permalink to &quot;Running the current tests and feedback loop&quot;">​</a></h1><p>T01&#39;s test subject is the first public full-stack request. The commands below are real checks, not empty gates parked for v1 features that do not exist yet.</p><h2 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-backend</span></span></code></pre></div><p>The script creates an isolated PostgreSQL container; SQLx tests run real migrations. The development database&#39;s data volume is never wiped by tests. Tests going through the Router verify liveness, readiness, public errors/request_id, OpenAPI, and the real database migration state. The startup configuration test runs the real API executable and checks that failures happen before listening and never leak credentials.</p><p>The migration test also holds the real PostgreSQL migration lock and then runs the migration command, verifying that it fails and exits within the configured deadline; HTTP tests use a database lock to verify queries do not wait forever.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-frontend</span></span></code></pre></div><p>Vitest / Testing Library drives the real views; MSW replaces only HTTP. Coverage runs from loading through success, failure messages, request_id and retry after recovery, to the service not responding: loading ends and retry is offered; every test creates a fresh QueryClient.</p><h2 id="dev-process-cleanup" tabindex="-1">Dev-process cleanup <a class="header-anchor" href="#dev-process-cleanup" aria-label="Permalink to &quot;Dev-process cleanup&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:tooling</span></span></code></pre></div><p>The test starts a real HTTP subprocess and lets it ignore SIGTERM. Even if the outer launcher exits first, stopping the development services must clean up the subprocess still holding the port. The test watches whether the service still responds, never counting internal signal invocations.</p><h2 id="real-browser" tabindex="-1">Real browser <a class="header-anchor" href="#real-browser" aria-label="Permalink to &quot;Real browser&quot;">​</a></h2><p>First-time Chromium preparation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e</span></span></code></pre></div><p>E2E creates an isolated database on dynamic ports, compiles and runs the real API, starts the Web app and visits it through Chromium. It checks that responses come from the real interfaces, pauses its own database container to verify readiness fails while liveness survives, then restores it. Logs, failure screenshots and traces go into the test-artifacts directory.</p><h2 id="main-check" tabindex="-1">Main check <a class="header-anchor" href="#main-check" aria-label="Permalink to &quot;Main check&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>It includes Rust fmt/clippy, frontend format/lint/typecheck, contract drift, boundary checks, process cleanup and backend/view tests, docs checks, and the web/docs builds. Daily checks never launch a browser; run <code>just e2e</code> after key journeys, and <code>just check-full</code> for full milestone acceptance. CI&#39;s manual entry can tick <code>run_e2e</code>; ordinary push/PR keeps the fast checks. Mobile is out of v1 scope (implementation ticket <a href="https://github.com/CaiZongyuan/axum-saas-template/issues/22" target="_blank" rel="noreferrer">#22</a> recorded as not planned; spec §15.2 stays as a design note); the shipped soak tests and business features each have their own checks — nothing idles, nothing pretends.</p><h2 id="red-→-green-during-implementation" tabindex="-1">Red → green during implementation <a class="header-anchor" href="#red-→-green-during-implementation" aria-label="Permalink to &quot;Red → green during implementation&quot;">​</a></h2><p>This ticket first observed, in order: unregistered routes returning 404, errors missing request_id, a missing 503 contract while the database was not ready, an unmigrated database falsely reporting ready, missing OpenAPI, a misconfigured setup still listening, and views without loading/failure feedback; then implemented each behavior one by one.</p><p>Later modules keep looping on the agreed public entry points, never substituting internal method-call counts or file existence for behavior.</p><hr><p>Source version：<code>da17f6123c09</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/docs/testing/t01-feedback-loop.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,24)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
